    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) != abs(dc):
                continue

            step_r = 1 if dr > 0 else -1
            step_c = 1 if dc > 0 else -1

            # Draw the diagonal connecting the two 1s, keeping any 6s visible.
            for k in range(abs(dr) + 1):
                r, c = r1 + k * step_r, c1 + k * step_c
                if grid[r][c] != 6:
                    out[r][c] = 1

            # A 6 on that segment extends along the perpendicular diagonal.
            for sr, sc in sixes:
                if (sr - r1) * dc != (sc - c1) * dr:
                    continue
                if not (min(r1, r2) <= sr <= max(r1, r2) and
                        min(c1, c2) <= sc <= max(c1, c2)):
                    continue

                # Segment slope +1 -> perpendicular slope -1, and vice versa.
                pdr, pdc = 1, -1 if step_r == step_c else 1
                for t in range(-h - w, h + w + 1):
                    r, c = sr + t * pdr, sc + t * pdc
                    if 0 <= r < h and 0 <= c < w and grid[r][c] != 1:
                        out[r][c] = 6

    return out
